import{_ as n,c as i,o as t,a2 as r}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Anpassung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/customize.md","filePath":"de/guide/customize.md","lastUpdated":1793163976000}'),l={name:"de/guide/customize.md"};function s(a,e,o,g,u,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="anpassung" tabindex="-1">Anpassung <a class="header-anchor" href="#anpassung" aria-label="Permalink to &quot;Anpassung&quot;">​</a></h1><p>Machen Sie NueZip zu Ihrem eigenen, indem Sie Ihr Archivverwaltungserlebnis personalisieren. Diese Anleitung deckt alles ab, was Sie anpassen können.</p><h2 id="allgemeine-einstellungen" tabindex="-1">Allgemeine Einstellungen <a class="header-anchor" href="#allgemeine-einstellungen" aria-label="Permalink to &quot;Allgemeine Einstellungen&quot;">​</a></h2><p>Öffnen Sie <strong>NueZip → Einstellungen</strong> (oder drücken Sie <code>Cmd+,</code>), um auf alle Anpassungsoptionen zuzugreifen.</p><h3 id="erscheinungsbild" tabindex="-1">Erscheinungsbild <a class="header-anchor" href="#erscheinungsbild" aria-label="Permalink to &quot;Erscheinungsbild&quot;">​</a></h3><ul><li><strong>Theme</strong>: Wählen Sie zwischen Hell, Dunkel oder System (folgt dem macOS-Erscheinungsbild)</li><li><strong>Symbolstil</strong>: Legen Sie monochromes oder farbiges Menüleistensymbol fest</li><li><strong>Sprache</strong>: Aus unterstützten Sprachen wählen (Englisch, 中文, 日本語, 한국어 und mehr)</li></ul><h2 id="komprimierungs-standardwerte" tabindex="-1">Komprimierungs-Standardwerte <a class="header-anchor" href="#komprimierungs-standardwerte" aria-label="Permalink to &quot;Komprimierungs-Standardwerte&quot;">​</a></h2><p>Legen Sie Ihre bevorzugten Komprimierungsstandardwerte fest:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Optionen</th><th>Beschreibung</th></tr></thead><tbody><tr><td><strong>Standardformat</strong></td><td>ZIP, 7z, TAR, GZIP, BZIP2, XZ</td><td>Archivformat für schnelle Komprimierung</td></tr><tr><td><strong>Kompressionsstufe</strong></td><td>Store, Fast, Normal, Maximum, Ultra</td><td>Abwägung zwischen Geschwindigkeit und Verhältnis</td></tr><tr><td><strong>Verschlüsselung</strong></td><td>None, AES-128, AES-256</td><td>Standardverschlüsselung für ZIP/7z-Archive</td></tr><tr><td><strong>Volume-Größe</strong></td><td>Benutzerdefiniert (MB)</td><td>Standard-Split-Größe für Multi-Volume-Archive</td></tr></tbody></table><h3 id="beispielkonfiguration" tabindex="-1">Beispielkonfiguration <a class="header-anchor" href="#beispielkonfiguration" aria-label="Permalink to &quot;Beispielkonfiguration&quot;">​</a></h3><p>Für den täglichen Gebrauch:</p><ul><li><strong>Format</strong>: ZIP</li><li><strong>Stufe</strong>: Normal</li><li><strong>Verschlüsselung</strong>: AES-256 (für sensible Dateien)</li><li><strong>Volume</strong>: Aus</li></ul><p>Für Archivierung:</p><ul><li><strong>Format</strong>: 7-Zip</li><li><strong>Stufe</strong>: Ultra</li><li><strong>Verschlüsselung</strong>: AES-256</li><li><strong>Volume</strong>: 4,7 GB (passt auf DVD)</li></ul><h2 id="extraktions-einstellungen" tabindex="-1">Extraktions-Einstellungen <a class="header-anchor" href="#extraktions-einstellungen" aria-label="Permalink to &quot;Extraktions-Einstellungen&quot;">​</a></h2><p>Passen Sie das Extraktionsverhalten an:</p><ul><li><strong>Standardmäßig in Unterordner extrahieren</strong>: Erstellt automatisch einen benannten Ordner beim Extrahieren</li><li><strong>Ordner nach Extraktion öffnen</strong>: Zeigt extrahierte Inhalte im Finder an</li><li><strong>Überschreibungsverhalten</strong>: Nachfragen, Immer überschreiben oder Vorhandene überspringen</li><li><strong>Dateidaten bewahren</strong>: Behält die ursprünglichen Zeitstempel aus dem Archiv bei</li></ul><h2 id="finder-erweiterung" tabindex="-1">Finder-Erweiterung <a class="header-anchor" href="#finder-erweiterung" aria-label="Permalink to &quot;Finder-Erweiterung&quot;">​</a></h2><p>Verwalten Sie die Finder-Kontextmenü-Integration:</p><ul><li><strong>Aktivieren/Deaktivieren</strong>: Schaltet die Menüeinträge per Rechtsklick ein oder aus</li><li><strong>Quick-Aktionen</strong>: Wählen Sie, welche Aktionen im Kontextmenü erscheinen <ul><li>Hier extrahieren</li><li>In Ordner extrahieren</li><li>Zu ZIP komprimieren</li><li>Mit Optionen komprimieren</li></ul></li></ul><p>Verwalten Sie diese unter: <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit → Erweiterungen → Finder-Erweiterungen</strong></p><h2 id="menuleisten-tray-symbol" tabindex="-1">Menüleisten- (Tray-)Symbol <a class="header-anchor" href="#menuleisten-tray-symbol" aria-label="Permalink to &quot;Menüleisten- (Tray-)Symbol&quot;">​</a></h2><p>Passen Sie das Menüleisten-Drop-Panel an:</p><ul><li><strong>In Menüleiste anzeigen</strong>: Tray-Symbol aktivieren/deaktivieren</li><li><strong>Panel automatisch schließen</strong>: Drop-Panel nach Extraktion schließen</li><li><strong>Zuletzt geöffnete Archive</strong>: Anzahl der anzuzeigenden kürzlichen Elemente</li><li><strong>Beim Schließen beenden</strong>: Ob die App im Hintergrund bleibt</li></ul><h2 id="benachrichtigungen" tabindex="-1">Benachrichtigungen <a class="header-anchor" href="#benachrichtigungen" aria-label="Permalink to &quot;Benachrichtigungen&quot;">​</a></h2><ul><li><strong>Abschlussbenachrichtigungen anzeigen</strong>: Benachrichtigung, wenn zeitaufwändige Vorgänge abgeschlossen sind</li><li><strong>Fehlerbenachrichtigungen anzeigen</strong>: Benachrichtigungen für fehlgeschlagene Vorgänge anzeigen</li><li><strong>Ton</strong>: Einen Ton abspielen, wenn Vorgänge abgeschlossen sind</li></ul><h2 id="allgemeine-einstellungen-1" tabindex="-1">Allgemeine Einstellungen <a class="header-anchor" href="#allgemeine-einstellungen-1" aria-label="Permalink to &quot;Allgemeine Einstellungen&quot;">​</a></h2><p>Greifen Sie in <strong>Einstellungen → Allgemein</strong> darauf zu:</p><ul><li><strong>Sprache</strong>: Zwischen Englisch, 中文, 日本語 und mehr wechseln</li><li><strong>Start bei Anmeldung</strong>: NueZip startet automatisch, wenn Sie sich anmelden</li><li><strong>Theme</strong>: Hell- oder Dunkelmodus (folgt standardmäßig dem System)</li><li><strong>Menüleistensymbol</strong>: Menüleistensymbol anzeigen oder ausblenden</li></ul><h2 id="tipps" tabindex="-1">Tipps <a class="header-anchor" href="#tipps" aria-label="Permalink to &quot;Tipps&quot;">​</a></h2><ul><li>Legen Sie Ihre bevorzugten Komprimierungsstandardwerte einmal fest, um die tägliche Archivierung zu beschleunigen</li><li>Aktivieren Sie „Start bei Anmeldung&quot;, damit NueZip stets nur einen Klick entfernt ist</li><li>Nutzen Sie die Finder-Erweiterung für den schnellsten Extraktions-/Komprimierungs-Workflow</li><li>Prüfen Sie den Ordnerzugriff regelmäßig in den Systemeinstellungen, um alles übersichtlich zu halten</li></ul>',31)])])}const m=n(l,[["render",s]]);export{c as __pageData,m as default};
